<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Giấy phép & chứng nhận | NALI Dental</title><?php renderSeo('Giấy phép, chứng nhận và đối tác | NALI Dental','Các giấy tờ và đối tác chỉ được hiển thị khi có xác minh nội bộ và được phép công bố.'); ?><link rel="stylesheet" href="common.css"><link rel="stylesheet" href="theme.css"><link rel="stylesheet" href="content-pages.css"></head><body><?php renderHeader(); ?><section class="content-hero"><h1>Bằng chứng chuyên môn</h1><p>Chỉ hiển thị giấy phép, chứng nhận và đối tác đã được xác minh cũng như được phép công khai.</p></section><main class="content-wrap"><div class="content-grid"><?php foreach($items as $i):?><article class="content-card"><?php if($i['image']):?><img src="<?=htmlspecialchars($i['image'])?>" alt="<?=htmlspecialchars($i['title'])?>" loading="lazy" style="width:100%;height:150px;object-fit:contain;margin-bottom:14px"><?php endif;?><p class="meta"><?=htmlspecialchars($labels[$i['item_type']]??$i['item_type'])?></p><h2><?=htmlspecialchars($i['title'])?></h2><?php if($i['issuer']):?><p><b>Đơn vị cấp/đối tác:</b> <?=htmlspecialchars($i['issuer'])?></p><?php endif;?><?php if($i['credential_code']):?><p><b>Số hiệu:</b> <?=htmlspecialchars($i['credential_code'])?></p><?php endif;?><p><?=nl2br(htmlspecialchars($i['description']??''))?></p><span class="trust-badge">✓ Đã xác minh</span><?php if($i['evidence_url'] && preg_match('#^https://#',$i['evidence_url'])):?><p><a href="<?=htmlspecialchars($i['evidence_url'],ENT_QUOTES,'UTF-8')?>" target="_blank" rel="noopener">Xem nguồn xác minh</a></p><?php endif;?></article><?php endforeach;?></div><?php if(!$items):?><div class="content-empty">Chưa có tài liệu đã xác minh được phép công khai. Trang này cố ý không dùng logo hoặc chứng nhận minh họa.</div><?php endif;?></main><?php renderFooter(); ?></body></html>
